import sys
from collections import deque

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n, m = map(int, input[ptr:ptr+2])
        ptr +=2
        adj = [[] for _ in range(n+1)]
        for __ in range(m):
            a, b = map(int, input[ptr:ptr+2])
            ptr +=2
            adj[a].append(b)
        res = [0]*(n+1)
        res[1] = 1
        q = deque()
        q.append(1)
        visited = [False]*(n+1)
        visited[1] = True
        has_loop = [False]*(n+1)
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v == u:
                    has_loop[u] = True
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
        for u in range(1, n+1):
            if u == 1:
                print(1, end=' ')
                continue
            if not visited[u]:
                print(0, end=' ')
                continue
            if has_loop[u]:
                print(-1, end=' ')
                continue
            q = deque()
            q.append((u, 1))
            visited_path = [False]*(n+1)
            visited_path[u] = True
            count = 0
            while q:
                node, cnt = q.popleft()
                if node == 1:
                    count += cnt
                    if count > 1:
                        break
                for neighbor in adj[node]:
                    if not visited_path[neighbor]:
                        visited_path[neighbor] = True
                        q.append((neighbor, cnt))
            if count == 0:
                print(0, end=' ')
            elif count == 1:
                print(1, end=' ')
            else:
                print(2, end=' ')
        print()

solve()
